css:
.pl { font-size: 11px; } .pl h3 { text-align:center; margin:0 } .pl .sub { text-align:center; margin:2px 0 10px }
.pl table { width:100%; border-collapse:collapse } .pl td, .pl th { border:1px solid #666; padding:3px 6px }
.pl .num { text-align:right } .pl .lbl { width:60% } .pl .net td { font-weight:bold; background:#eef }
.pl .sec { background:#f0f0f0; font-weight:bold } .pl .sign { border:0; text-align:center; width:50%; padding-top:36px }
.pl .note { font-size:9px; color:#555; margin-top:8px }
